// Port of supabase/functions/send-purchase-reminder-email.
// Cron job, once a day: writes today's purchase-reminder message (one per UTC date, generated by an AI
// gateway if missing), then emails it to accounts that have no active enrolment and have not yet
// received today's reminder.
//
// Authorisation: `Authorization: Bearer <CRON_SECRET>`. (The original had no check.)
// Config (env): LOVABLE_API_KEY, LOVABLE_API_URL (optional override), and mail settings read by
// functions/_shared/mail.js (MAIL_MODE, SMTP_*). Dry-run mail is the default.
//
// Deliberate difference: the original listed only the first page of auth users (50). This port reads
// all accounts that have an email.
import express from "express";
import { query } from "../_shared/db.js";
import { sendMail } from "../_shared/mail.js";

const DEFAULT_AI_URL = "https://ai.gateway.lovable.dev/v1/chat/completions";
const BATCH_SIZE = 10;
const FALLBACK_SUBJECT = "📚 Your courses are waiting for you at SimpleLecture!";
const FALLBACK_BODY = "You've taken the first step by signing up — now take the next one! Explore our courses designed to help you succeed. With AI-powered tutoring and expert content, we've got everything you need. — Team SimpleLecture";

export const router = express.Router();

const escapeHtml = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

function emailHtml(userName, messageBody) {
  // The message body is inserted as HTML, as in the original. It is generated text, not user input.
  return `
    <div style="font-family: 'Segoe UI', Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 0; background-color: #ffffff;">
      <div style="background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%); padding: 40px 30px; text-align: center; border-radius: 0 0 24px 24px;">
        <h1 style="color: #ffffff; margin: 0; font-size: 28px; font-weight: 700;">SimpleLecture</h1>
        <p style="color: rgba(255,255,255,0.85); margin: 8px 0 0; font-size: 14px;">Your courses are waiting! 📚</p>
      </div>
      <div style="padding: 36px 30px;">
        <p style="color: #374151; font-size: 18px; margin: 0 0 8px;">Hi ${escapeHtml(userName)},</p>
        <div style="background-color: #f8f7ff; border-left: 4px solid #6366f1; padding: 20px 24px; margin: 24px 0; border-radius: 0 12px 12px 0;">
          <p style="color: #4b5563; font-size: 16px; line-height: 1.7; margin: 0;">
            ${messageBody}
          </p>
        </div>
        <div style="text-align: center; margin: 32px 0;">
          <a href="https://simplelecture.com" style="display: inline-block; background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%); color: #ffffff; text-decoration: none; padding: 14px 36px; border-radius: 8px; font-size: 16px; font-weight: 600;">
            Browse Courses →
          </a>
        </div>
      </div>
      <div style="padding: 20px 30px; text-align: center; border-top: 1px solid #f3f4f6;">
        <p style="color: #9ca3af; font-size: 12px; margin: 0;">
          You're receiving this because you haven't explored our courses yet 💜
        </p>
      </div>
    </div>`;
}

async function generateMessage(today) {
  const apiKey = process.env.LOVABLE_API_KEY;
  if (!apiKey) throw new Error("LOVABLE_API_KEY is not configured");
  const randomSeed = Math.floor(Math.random() * 100000) + 1;

  const aiResponse = await fetch(process.env.LOVABLE_API_URL || DEFAULT_AI_URL, {
    method: "POST",
    headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "google/gemini-3-flash-preview",
      messages: [
        {
          role: "system",
          content: `You are SimpleLecture's marketing assistant. Write a short, compelling email message (3-4 sentences) encouraging a student who has signed up but hasn't enrolled in any course yet. Highlight the benefits of SimpleLecture courses — AI tutoring, expert content, practice questions, live classes. Create urgency but stay warm and friendly. Sign off as "Team SimpleLecture". Also generate a catchy email subject line.

Respond in this exact JSON format:
{"subject_line": "your subject here", "message_body": "your message here"}`,
        },
        {
          role: "user",
          content: `Generate today's purchase reminder message. Date: ${today}. Random seed: ${randomSeed}. Be unique and different from previous messages.`,
        },
      ],
    }),
  });
  if (!aiResponse.ok) {
    console.error("[Purchase Reminder] AI error:", aiResponse.status);
    throw new Error(`AI gateway error: ${aiResponse.status}`);
  }

  const aiData = await aiResponse.json();
  const content = aiData.choices?.[0]?.message?.content || "";
  try {
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error("No JSON found");
    const parsed = JSON.parse(jsonMatch[0]);
    return { subjectLine: parsed.subject_line, messageBody: parsed.message_body };
  } catch {
    return { subjectLine: FALLBACK_SUBJECT, messageBody: content || FALLBACK_BODY };
  }
}

// Today's message, created when missing. A concurrent insert (unique violation) is resolved by reading
// the row the other instance wrote.
async function todaysMessage(today) {
  const select = "SELECT subject_line, message_body FROM public.purchase_reminder_messages WHERE message_date = $1::date LIMIT 1";
  const { rows } = await query(select, [today]);
  if (rows[0]) {
    console.log("[Purchase Reminder] Reusing existing message");
    return { subjectLine: rows[0].subject_line, messageBody: rows[0].message_body };
  }

  console.log("[Purchase Reminder] Generating new AI message...");
  const generated = await generateMessage(today);
  try {
    await query(
      "INSERT INTO public.purchase_reminder_messages (message_date, subject_line, message_body) VALUES ($1::date, $2, $3)",
      [today, generated.subjectLine, generated.messageBody]
    );
  } catch (err) {
    if (err.code !== "23505") throw err;
    const { rows: again } = await query(select, [today]);
    return { subjectLine: again[0].subject_line, messageBody: again[0].message_body };
  }
  console.log("[Purchase Reminder] Message generated:", generated.subjectLine);
  return generated;
}

async function logEmail(user, today, status, errorMessage) {
  await query(
    `INSERT INTO public.purchase_reminder_email_logs (user_id, email, sent_date, status, error_message)
     VALUES ($1, $2, $3::date, $4, $5)`,
    [user.id, user.email, today, status, errorMessage ?? null]
  );
}

router.all("/", async (req, res) => {
  const json = (status, body) => res.status(status).json(body);
  if (req.method === "OPTIONS") return res.status(200).end();

  const cronSecret = process.env.CRON_SECRET;
  if (!cronSecret) return json(500, { error: "CRON_SECRET is not configured" });
  if (req.headers.authorization !== `Bearer ${cronSecret}`) return json(401, { error: "Unauthorized" });

  try {
    const today = new Date().toISOString().split("T")[0];
    console.log(`[Purchase Reminder] Starting for date: ${today}`);

    const { subjectLine, messageBody } = await todaysMessage(today);

    const { rows: accounts } = await query(
      `SELECT u.id, u.email, p.full_name
         FROM auth.users u
         JOIN public.profiles p ON p.id = u.id
        WHERE u.email IS NOT NULL AND u.email <> ''`
    );
    if (accounts.length === 0) return json(200, { message: "No users", sent: 0 });

    // Accounts with no active enrolment.
    const { rows: enrolled } = await query(
      "SELECT DISTINCT student_id FROM public.enrollments WHERE is_active = true AND student_id = ANY($1::uuid[])",
      [accounts.map((a) => a.id)]
    );
    const enrolledSet = new Set(enrolled.map((e) => e.student_id));
    const nonPurchasers = accounts.filter((a) => !enrolledSet.has(a.id));
    console.log(`[Purchase Reminder] ${nonPurchasers.length} users without purchases (${enrolledSet.size} enrolled)`);

    if (nonPurchasers.length === 0) return json(200, { message: "All users have enrolled", sent: 0 });

    const { rows: sentRows } = await query(
      "SELECT user_id FROM public.purchase_reminder_email_logs WHERE sent_date = $1::date AND user_id = ANY($2::uuid[])",
      [today, nonPurchasers.map((a) => a.id)]
    );
    const alreadySent = new Set(sentRows.map((r) => r.user_id));
    const usersToEmail = nonPurchasers
      .filter((a) => !alreadySent.has(a.id))
      .map((a) => ({ id: a.id, email: a.email, full_name: a.full_name || null }));
    console.log(`[Purchase Reminder] ${usersToEmail.length} users to email`);

    if (usersToEmail.length === 0) return json(200, { message: "All reminders already sent today", sent: 0 });

    if ((process.env.MAIL_MODE || "dry-run") === "smtp" && (!process.env.SMTP_HOST || !process.env.SMTP_USER || !process.env.SMTP_PASS)) {
      throw new Error("SMTP credentials not configured");
    }

    let sentCount = 0;
    let failedCount = 0;
    for (let i = 0; i < usersToEmail.length; i += BATCH_SIZE) {
      const batch = usersToEmail.slice(i, i + BATCH_SIZE);
      await Promise.all(
        batch.map(async (user) => {
          try {
            await sendMail({
              to: user.email,
              subject: subjectLine,
              html: emailHtml(user.full_name || "Student", messageBody),
              text: `${subjectLine}\n\n${messageBody}`,
            });
            await logEmail(user, today, "sent", null);
            sentCount++;
          } catch (err) {
            console.error(`[Purchase Reminder] Failed for ${user.email}:`, err.message);
            failedCount++;
            await logEmail(user, today, "failed", (err.message || "").substring(0, 500));
          }
        })
      );
      if (i + BATCH_SIZE < usersToEmail.length) {
        await new Promise((resolve) => setTimeout(resolve, 500));
      }
    }

    console.log(`[Purchase Reminder] Done! Sent: ${sentCount}, Failed: ${failedCount}`);
    return json(200, {
      message: "Purchase reminder emails processed",
      sent: sentCount,
      failed: failedCount,
      total: usersToEmail.length,
      subject: subjectLine,
    });
  } catch (error) {
    console.error("[Purchase Reminder] Fatal error:", error?.message);
    return json(500, { error: error.message || "Internal server error" });
  }
});

export default router;
